package puppetdb

import (
	"strconv"
	"strings"

	"github.com/prometheus/common/model"

	promlabels "github.com/prometheus/prometheus/model/labels"
	"github.com/prometheus/prometheus/util/strutil"
)

const parameterLabelNameChars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_"

type Resource struct {
	Certname    string     `json:"certname"`
	Resource    string     `json:"resource"`
	Type        string     `json:"type"`
	Title       string     `json:"title"`
	Exported    bool       `json:"exported"`
	Tags        []string   `json:"tags"`
	File        string     `json:"file"`
	Environment string     `json:"environment"`
	Parameters  Parameters `json:"parameters"`
}

type Parameters map[string]interface{}

func (p *Parameters) toLabels() model.LabelSet {
	collected := make(map[string]string)

	for k, v := range *p {
		var labelValue string
		switch value := v.(type) {
		case string:
			labelValue = value
		case bool:
			labelValue = strconv.FormatBool(value)
		case []string:
			labelValue = separator + strings.Join(value, separator) + separator
		case []interface{}:
			if len(value) == 0 {
				continue
			}
			n := len(value)
			values := make([]string, n)
			for i, v := range value {
				switch value := v.(type) {
				case string:
					values[i] = value
				case bool:
					values[i] = strconv.FormatBool(value)
				case []string:
					values[i] = separator + strings.Join(value, separator) + separator
				}
			}
			joined := strings.Join(values, separator)
			labelValue = joined
		case map[string]interface{}:
			subParameter := Parameters(value)
			nested := subParameter.toLabels()
			prefix := strutil.SanitizeLabelName(k + "_")
			for subk, subv := range nested {
				fullName := prefix + string(subk)
				fullValue := string(subv)
				collected[fullName] = fullValue
			}
		default:
			continue
		}
		if labelValue == "" {
			continue
		}
		var nameBuilder strings.Builder
		nameBuilder.Grow(len(k))
		for _, r := range k {
			if strings.ContainsRune(parameterLabelNameChars, r) {
				nameBuilder.WriteRune(r)
			} else {
				nameBuilder.WriteByte('_')
			}
		}
		sanitized := nameBuilder.String()
		name := strutil.SanitizeLabelName(sanitized)
		collected[name] = labelValue
	}

	converted := promlabels.FromMap(collected)
	mapped := converted.Map()
	result := make(model.LabelSet, len(mapped))
	for name, value := range mapped {
		labelName := model.LabelName(name)
		labelValue := model.LabelValue(value)
		result[labelName] = labelValue
	}
	return result
}

